create or replace function public.business_campaign_detail(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from (select c.id,c.name,c.campaign_type,c.goal,c.status,c.created_at,coalesce(sum(o.visits) filter(where o.metric_date between p_start::date and p_end::date),0) visits,coalesce(sum(o.check_ins) filter(where o.metric_date between p_start::date and p_end::date),0) check_ins,coalesce(sum(o.reviews) filter(where o.metric_date between p_start::date and p_end::date),0) reviews,coalesce(sum(o.attributed_users) filter(where o.metric_date between p_start::date and p_end::date),0) attributed_users from enterprise_partner_campaigns c left join enterprise_partner_campaign_outcomes o on o.campaign_id=c.id where c.network_id in(select id from enterprise_partner_networks where owner_business_id=p_business_id) and c.created_at <= p_end group by c.id,c.name,c.campaign_type,c.goal,c.status,c.created_at) x; $$;
